#include <stdio.h>
#include <stdlib.h>

int main(void) {
    long input = -1;
    if (input < 0) {
        puts("A count cannot be negative");
        return EXIT_FAILURE;
    }
    unsigned long count = (unsigned long)input;
    printf("Count: %lu\n", count);
    return EXIT_SUCCESS;
}

#include <stdio.h>

int main(void) {
    long price_cents = 1299;
    printf("$%ld.%02ld\n", price_cents / 100, price_cents % 100);
    return 0;
}
